import test from 'node:test';
import assert from 'node:assert/strict';
import { JSDOM } from 'jsdom';
import { parseCodex } from '../packages/core/src/codex';
import { parseClaude } from '../packages/core/src/claude';
import { renderSidecar, renderDetail } from '../packages/vscode/src/render';

// Synthetic content; source shapes were grounded in the plugin rendering workbook (archived/PLUGIN_RENDERING_REFERENCE.md, kept locally).
// Native-plugin screenshots are evidence for the design, not generated by this test.
for (const provider of ['codex', 'claude'] as const) {
  test(`${provider}: request Markdown uses the full source and excludes attached IDE background`, () => {
    const body = '**核对展示**\n\n- 读取 `README.md`\n- 保留原始顺序\n\n```ts\nconst mode = "read";\n```\n\n' + '完整的问题正文。'.repeat(35);
    const prompt = '# Context from my IDE setup:\n\n## Open tabs:\n- PRIVATE_CONTEXT_ONLY\n\n## My request:\n' + body;
    const record = provider === 'codex'
      ? { type: 'response_item', payload: { type: 'message', role: 'user', content: [{ type: 'input_text', text: prompt }] } }
      : { type: 'user', uuid: 'request', sessionId: 'sample', message: { role: 'user', content: [{ type: 'text', text: prompt }] } };
    const session = (provider === 'codex' ? parseCodex : parseClaude)({ text: JSON.stringify(record), file: '/synthetic/reference.jsonl', projectPath: '/synthetic' });
    const before = JSON.stringify(session);
    const dom = new JSDOM(renderSidecar({ projectName: 'fixture', session, nonce: 'fixture' }));
    const question = dom.window.document.querySelector('.question-text')!;
    assert.equal(question.querySelector('strong')!.textContent, '核对展示');
    assert.equal(question.querySelectorAll('li').length, 2);
    assert.equal(question.querySelector('li code')!.textContent, 'README.md');
    assert.equal(question.querySelector('pre code')!.textContent, 'const mode = "read";\n');
    assert.ok(question.textContent!.includes('完整的问题正文。'.repeat(35)), 'Clamp the view, not the source before Markdown parsing');
    assert.ok(!question.textContent!.includes('PRIVATE_CONTEXT_ONLY'));
    assert.equal(dom.window.document.querySelectorAll('.turn-question').length, 1);
    const request = session.items.find(item => item.kind === 'request')!;
    assert.equal(dom.window.document.querySelector('.turn-question')!.getAttribute('data-text-id'), request.id);
    // The full text opens in the editor area rather than growing the card in place.
    const more = dom.window.document.querySelector('.question-more')!;
    assert.ok(more.hasAttribute('data-open-text')); assert.equal(more.getAttribute('data-item-id'), request.id);
    const detail = new JSDOM(renderDetail({ item: request, provider, nonce: 'fixture', kept: false }));
    assert.equal(detail.window.document.querySelector('.markdown strong')!.textContent, '核对展示');
    assert.equal(JSON.stringify(session), before, 'Presentation must not modify records or their identity');
    detail.window.close(); dom.window.close();
  });
}

test('request Markdown has the same no-HTML and no-network protections as public prose', () => {
  const source = '**Text** <script>bad()</script> ![remote](https://example.com/image.png) [run](command:danger)';
  const session = parseClaude({ text: JSON.stringify({ type: 'user', uuid: 'u', sessionId: 's', message: { content: source } }), file: '/synthetic/s.jsonl', projectPath: '/synthetic' });
  const dom = new JSDOM(renderSidecar({ projectName: 'f', session, nonce: 'fixture' }));
  const question = dom.window.document.querySelector('.question-text')!;
  assert.equal(question.querySelectorAll('script,img,iframe,a').length, 0);
  assert.equal(question.querySelector('strong')!.textContent, 'Text');
  assert.ok(question.textContent!.includes('<script>bad()</script>'));
  dom.window.close();
});
